func (s *Server) GetUser(ctx context.Context, req *pb.Req) (*pb.Resp, error) {
    if dl, ok := ctx.Deadline(); ok && time.Until(dl) <= 0 {
        return nil, status.Error(codes.DeadlineExceeded, "budget exhausted")
    }
    // child context inherits the incoming deadline; the timeout only shortens it
    ctx, cancel := context.WithTimeout(ctx, s.maxHopBudget)
    defer cancel()
    return s.users.Get(ctx, req)
}
